mapper.select:
SELECT `email`, `name`, `store_name` AS `storeName`, `shop_id` AS `shopId`, `usertype`, `style`, `level`, `phone`, `address`, `address_detail` AS `addressDetail`, `created_at` AS `createdAt`, `updated_at` AS `updatedAt`, `last_logout_at` AS `lastLogOutAt` FROM `cors`.`users`
AND `store_name` = #{storeName} AND `level` >= #{myLevel}
AND `level` = #{filterLevel}
AND (`name` LIKE CONCAT('%', #{keyword}, '%') OR `email` LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY `level` ASC, `created_at` DESC

SELECT `email`, `name`, `store_name` AS `storeName`, `shop_id` AS `shopId`, `usertype`, `style`, `level`, `phone`, `address`, `address_detail` AS `addressDetail`, `created_at` AS `createdAt`, `updated_at` AS `updatedAt`, `last_logout_at` AS `lastLogOutAt` FROM `cors`.`users`
AND `shop_id` = #{shopId} AND `level` >= #{myLevel}
AND `level` = #{filterLevel}
AND (`name` LIKE CONCAT('%', #{keyword}, '%') OR `email` LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY `level` ASC, `created_at` DESC
